-- SG / IT 技术词条扩充。释义为平台自编学习内容，不冒充官方真题或第三方词典。
INSERT OR IGNORE INTO vocabulary
(id,term,language,reading,meaning_zh,meaning_ja,meaning_en,example,source_module,mastery)
VALUES
('sg-v007-risk-assessment','リスクアセスメント','ja','りすくあせすめんと','风险评估：识别风险并分析发生可能性和影响。','リスクを特定し、発生可能性や影響を分析すること。','Risk assessment identifies risks and evaluates likelihood and impact.','導入前にリスクアセスメントを行う。','リスク管理',0),
('sg-v007-risk-treatment','リスク対応','ja','りすくたいおう','风险处置：规避、降低、转移或接受风险。','リスクを回避・低減・移転・受容すること。','Risk treatment avoids, reduces, transfers, or accepts risk.','リスク対応方針を決める。','リスク管理',0),
('sg-v007-threat','脅威','ja','きょうい','威胁：可能造成损害的潜在原因或事件。','損害を引き起こす可能性のある原因や事象。','A threat is a potential cause of harm.','自然災害も脅威になり得る。','情報セキュリティ',0),
('sg-v007-asset','情報資産','ja','じょうほうしさん','信息资产：需要保护的信息以及相关系统、设备和媒体。','保護すべき情報と、それを扱うシステムや媒体。','Information assets include information and systems that handle it.','情報資産台帳を更新する。','情報セキュリティ',0),
('sg-v007-access-control','アクセス制御','ja','あくせすせいぎょ','访问控制：依据身份和权限限制资源访问。','識別情報や権限に基づき資源へのアクセスを制限すること。','Access control restricts access based on identity and permissions.','機密ファイルにアクセス制御を設定する。','アクセス管理',0),
('sg-v007-identification','識別','ja','しきべつ','识别：通过标识区分用户或设备。','識別子によって利用者や機器を区別すること。','Identification distinguishes users or devices by an identifier.','ユーザーIDで利用者を識別する。','アクセス管理',0),
('sg-v007-auth-factor','認証要素','ja','にんしょうようそ','认证要素：知识、持有物、生物特征等身份验证因素。','知識・所持・生体など本人確認に用いる要素。','Authentication factors include knowledge, possession, and biometrics.','パスワードは知識要素である。','アクセス管理',0),
('sg-v007-password-policy','パスワードポリシー','ja','ぱすわーどぽりしー','密码策略：组织对密码设置和管理的要求。','パスワードの設定や管理方法を定めた規則。','A password policy defines password requirements and management.','社内ポリシーに従って管理する。','アクセス管理',0),
('sg-v007-brute-force','総当たり攻撃','ja','そうあたりこうげき','暴力破解：尝试大量密码或密钥组合。','多数のパスワードや鍵の候補を順に試す攻撃。','A brute-force attack tries many possible passwords or keys.','試行回数を制限して攻撃を抑える。','脅威と攻撃',0),
('sg-v007-dictionary-attack','辞書攻撃','ja','じしょこうげき','字典攻击：使用常见密码词表猜测密码。','よく使われる単語やパスワードの一覧を使う攻撃。','A dictionary attack tries passwords from a list of likely words.','推測されやすい単語を避ける。','脅威と攻撃',0),
('sg-v007-social-engineering','ソーシャルエンジニアリング','ja','そーしゃるえんじにありんぐ','社会工程学：利用人的心理或信任骗取信息或诱导操作。','人の心理や信頼を悪用して情報を得たり操作させたりする手口。','Social engineering manipulates people to disclose information or act.','電話で秘密情報を聞き出す手口がある。','脅威と攻撃',0),
('sg-v007-malware','マルウェア','ja','まるうぇあ','恶意软件：用于破坏、窃取、监视或非法控制的软件。','破壊や情報窃取などを目的とする悪意あるソフトウェア。','Malware is software designed to harm or compromise systems.','不審な添付ファイルを開かない。','脅威と攻撃',0),
('sg-v007-dos','DoS攻撃','ja','どすこうげき','拒绝服务攻击：使服务无法正常提供的攻击。','サービスを利用困難にする攻撃。','A denial-of-service attack disrupts service availability.','異常な通信を監視する。','脅威と攻撃',0),
('sg-v007-ddos','DDoS攻撃','ja','でぃーどすこうげき','分布式拒绝服务攻击：利用多个设备同时发起攻击。','複数の機器から大量の通信を送りサービスを妨害する攻撃。','A DDoS attack floods a service from many sources.','DDoS対策サービスを利用する。','脅威と攻撃',0),
('sg-v007-patch','セキュリティパッチ','ja','せきゅりてぃぱっち','安全补丁：修复漏洞或安全缺陷的软件更新。','脆弱性などを修正する更新プログラム。','A security patch fixes vulnerabilities or security defects.','検証後にパッチを適用する。','脆弱性管理',0),
('sg-v007-logging','ログ管理','ja','ろぐかんり','日志管理：收集、保护、保存和分析系统记录。','ログを収集・保護・保存し、必要に応じて分析すること。','Log management collects, protects, retains, and analyzes records.','ログの保存期間を定める。','運用管理',0),
('sg-v007-incident','セキュリティインシデント','ja','せきゅりてぃいんしでんと','安全事件：影响或可能影响信息安全的事件。','情報セキュリティに影響する、または影響するおそれのある事象。','A security incident affects or may affect information security.','速やかに担当者へ報告する。','インシデント対応',0),
('sg-v007-containment','封じ込め','ja','ふうじこめ','遏制：限制安全事件影响范围，避免损害扩大。','被害や影響範囲が拡大しないようにする対応。','Containment limits the spread and impact of an incident.','感染端末をネットワークから隔離する。','インシデント対応',0),
('sg-v007-bcp','事業継続計画','ja','じぎょうけいぞくけいかく','业务连续性计划（BCP）：灾害或故障时维持并恢复重要业务的计划。','災害や障害時に重要業務を継続・復旧するための計画。','A business continuity plan maintains and restores critical operations.','BCPの訓練を定期的に行う。','事業継続',0),
('sg-v007-redundancy','冗長化','ja','じょうちょうか','冗余：配置备用组件或路径，减少单点故障影响。','障害に備えて予備の機器や経路を用意すること。','Redundancy provides backup components or paths.','サーバーを冗長化する。','システム運用',0),
('sg-v007-failover','フェールオーバー','ja','ふぇーるおーばー','故障切换：主系统故障时切换到备用系统。','主系の障害時に待機系へ切り替えること。','Failover switches to a standby system when the primary fails.','障害時に待機系へ切り替える。','システム運用',0),
('sg-v007-load-balancing','負荷分散','ja','ふかぶんさん','负载均衡：把请求分配给多个服务器或资源。','複数のサーバーなどに処理要求を振り分けること。','Load balancing distributes requests across resources.','負荷分散で応答性能を改善する。','ネットワーク',0),
('sg-v007-firewall','ファイアウォール','ja','ふぁいあうぉーる','防火墙：按规则允许或阻止网络通信。','通信ルールに基づいて通信を許可または遮断する仕組み。','A firewall permits or blocks traffic according to rules.','不要な通信を遮断する。','ネットワーク',0),
('sg-v007-vpn','VPN','en','ぶいぴーえぬ','虚拟专用网络：通过受保护的隧道传输网络通信。','保護された仮想的な通信路を構築する技術。','A VPN creates a protected virtual communication path.','VPN経由で社内システムに接続する。','ネットワーク',0),
('sg-v007-dhcp','DHCP','en','でぃーえいちしーぴー','动态主机配置协议：自动分配 IP 地址等网络配置。','IPアドレスなどのネットワーク設定を自動配布するプロトコル。','DHCP automatically assigns IP addresses and network settings.','端末はDHCPでIPアドレスを取得する。','ネットワーク',0),
('sg-v007-ip','IPアドレス','ja','あいぴーあどれす','IP 地址：用于在 IP 网络中寻址的编号。','IPネットワークで通信先を指定するための番号。','An IP address identifies a network interface for communication.','サーバーのIPアドレスを確認する。','ネットワーク',0),
('sg-v007-public-key','公開鍵','ja','こうかいかぎ','公钥：可公开使用的密钥，可用于验证签名等。','公開鍵暗号方式で公開して利用する鍵。','A public key is openly shared in a public-key system.','公開鍵で電子署名を検証する。','暗号技術',0),
('sg-v007-private-key','秘密鍵','ja','ひみつかぎ','私钥：必须保密的密钥，可用于解密或生成签名。','安全に保管すべき、公開鍵と対になる鍵。','A private key must be protected and may be used to decrypt or sign.','秘密鍵をソースコードに埋め込まない。','暗号技術',0),
('sg-v007-certificate','電子証明書','ja','でんししょうめいしょ','数字证书：将公钥与主体身份关联的电子证明。','公開鍵と主体の情報を結び付ける電子的な証明書。','A digital certificate binds a public key to an identity.','証明書の期限と発行者を確認する。','暗号技術',0),
('sg-v007-ca','認証局','ja','にんしょうきょく','证书颁发机构（CA）：签发和管理数字证书的可信机构。','電子証明書を発行・管理する機関。','A certificate authority issues and manages digital certificates.','証明書の発行元を確認する。','暗号技術',0),
('sg-v007-symmetric','共通鍵暗号方式','ja','きょうつうかぎあんごうほうしき','对称加密：加密和解密使用同一个密钥。','暗号化と復号に同じ鍵を使う方式。','Symmetric encryption uses the same key to encrypt and decrypt.','共通鍵を安全に共有する。','暗号技術',0),
('sg-v007-asymmetric','公開鍵暗号方式','ja','こうかいかぎあんごうほうしき','非对称加密：使用公钥和私钥组成的密钥对。','公開鍵と秘密鍵のペアを用いる方式。','Asymmetric cryptography uses a public and private key pair.','公開鍵暗号は鍵配送などに使われる。','暗号技術',0),
('sg-v007-signature','デジタル署名','ja','でじたるしょめい','数字签名：验证数据来源和完整性的技术，不等同于加密。','データの作成者や完全性を検証するための技術。','A digital signature verifies origin and integrity; it is not encryption.','署名しても内容が秘密になるわけではない。','暗号技術',0),
('sg-v007-primary-key','主キー','ja','しゅきー','主键：唯一标识表中每条记录的字段或字段组合。','テーブルの各行を一意に識別する列または列の組み合わせ。','A primary key uniquely identifies each row.','主キーの値は重複させない。','データベース',0),
('sg-v007-normalization','正規化','ja','せいきか','数据库规范化：减少数据重复和更新异常。','データの重複や更新時の不整合を減らすために表を整理すること。','Normalization reduces redundancy and update anomalies.','更新異常を防ぐため正規化する。','データベース',0),
('sg-v007-acid','ACID特性','ja','えーしーあいでぃーとくせい','事务 ACID：原子性、一致性、隔离性、持久性。','原子性・一貫性・分離性・永続性を表す特性。','ACID means atomicity, consistency, isolation, and durability.','決済処理ではACID特性が重要である。','データベース',0),
('sg-v007-input-validation','入力値検証','ja','にゅうりょくちけんしょう','输入验证：检查输入是否符合预期格式、范围和规则。','入力が想定した形式や範囲に合うか確認すること。','Input validation checks expected formats, ranges, and rules.','サーバー側でも入力値を検証する。','アプリケーションセキュリティ',0),
('sg-v007-output-encoding','出力エンコーディング','ja','しゅつりょくえんこーでぃんぐ','输出编码：按上下文安全处理特殊字符，降低脚本注入风险。','出力先の文脈に応じて特殊文字を安全にエンコードすること。','Output encoding safely encodes special characters for the output context.','HTML出力では適切にエスケープする。','アプリケーションセキュリティ',0),
('sg-v007-session','セッション','ja','せっしょん','会话：在多个请求间关联同一用户或状态的机制。','複数のリクエストにまたがって利用者や状態を関連付ける仕組み。','A session links a user or state across requests.','セッションIDを安全に管理する。','Web技術',0),
('sg-v007-cookie','Cookie','en','クッキー','Cookie：浏览器保存并按条件随请求发送的小段数据。','ブラウザに保存され、条件に応じてリクエストとともに送信されるデータ。','A cookie is data stored by a browser and sent with matching requests.','認証CookieにSecure属性を設定する。','Web技術',0),
('sg-v007-cors','CORS','en','コルス','跨源资源共享：通过响应头控制浏览器是否允许跨源读取资源。','異なるオリジン間でブラウザがリソースを読み取れるか制御する仕組み。','CORS controls cross-origin browser access using response headers.','許可するオリジンを限定する。','Web技術',0),
('sg-v007-https','HTTPS','en','えいちてぃーてぃーぴーえす','通过 TLS 保护的 HTTP 通信。','TLSによって保護されたHTTP通信。','HTTPS is HTTP protected by TLS.','ログイン画面にはHTTPSを使用する。','Web技術',0),
('sg-v007-saas','SaaS','en','サース','软件即服务：通过网络使用服务商运营的软件。','提供者が運用するソフトウェアをネットワーク経由で利用する形態。','SaaS provides software over a network.','メールサービスはSaaSの例である。','クラウド',0),
('sg-v007-paas','PaaS','en','パース','平台即服务：提供应用开发和运行环境。','アプリケーションの開発・実行環境を提供する形態。','PaaS provides a platform to develop and run applications.','アプリをPaaS上に配置する。','クラウド',0),
('sg-v007-iaas','IaaS','en','アイアース','基础设施即服务：提供虚拟服务器、网络、存储等资源。','仮想サーバーやネットワークなどの基盤資源を提供する形態。','IaaS provides infrastructure resources such as virtual servers and storage.','OS管理の責任範囲を確認する。','クラウド',0),
('sg-v007-version-control','バージョン管理','ja','ばーじょんかんり','版本控制：记录代码变更历史，支持协作、比较和回退。','ソースコードの変更履歴を記録し、比較や復元を可能にすること。','Version control records changes and supports collaboration and rollback.','変更をコミットして履歴を残す。','ソフトウェア開発',0),
('sg-v007-regression-test','回帰テスト','ja','かいきてすと','回归测试：确认修改没有破坏既有功能。','変更によって既存機能に不具合が生じていないか確認するテスト。','Regression testing checks that changes have not broken existing behavior.','修正後に回帰テストを行う。','テスト',0),
('sg-v007-sla','SLA','en','えすえるえー','服务级别协议：服务商与客户约定的服务水平。','サービス提供者と利用者が合意するサービス水準。','An SLA defines agreed service levels.','SLAに可用性目標を明記する。','サービス管理',0),
('sg-v007-kpi','KPI','en','けーぴーあい','关键绩效指标：衡量目标进展或达成情况的指标。','目標の達成状況を測定するための重要な指標。','A KPI measures progress toward an objective.','対応時間をKPIとして追跡する。','マネジメント',0),
('sg-v007-pdca','PDCAサイクル','ja','ぴーでぃーしーえーさいくる','计划、执行、检查、改进循环，用于持续改善。','計画・実行・評価・改善を繰り返す継続的改善の手法。','PDCA means plan, do, check, and act.','監査結果を改善計画に反映する。','マネジメント',0),
('sg-v007-segregation','職務分掌','ja','しょくむぶんしょう','职责分离：将关键职责分配给不同人员，降低错误和舞弊风险。','重要な業務を複数の担当者に分け、不正や誤りを防ぐこと。','Segregation of duties separates critical tasks to reduce fraud and error.','申請者と承認者を分ける。','ガバナンス',0),
('sg-v007-data-minimization','データ最小化','ja','でーたさいしょうか','数据最小化：只收集和保留达成目的所必需的数据。','目的に必要な範囲に限ってデータを収集・保存する考え方。','Data minimization limits collection and retention to what is necessary.','不要な個人情報を収集しない。','プライバシー',0),
('sg-v007-3-2-1-backup','3-2-1バックアップ','ja','さんにいちばっくあっぷ','3-2-1 备份原则：三份副本、两种介质、一份异地保存。','データを3つ保持し、2種類の媒体を使い、1つを別の場所に保管する考え方。','The 3-2-1 rule keeps three copies on two media types, with one off-site.','復旧テストも定期的に行う。','事業継続',0);
